#!/usr/bin/env python
"""Generate each UI kit's ``contract.ts``; check Go and JS kits generate the same types.

python scripts/contracts.py build|check    # needs npm ci in ui/ (and js/, go for check)
"""

import argparse
import difflib
import importlib
import re
import subprocess
import sys
import tempfile
from pathlib import Path
from typing import Any, ClassVar

import yaml

REPO_ROOT = Path(__file__).resolve().parent.parent
UI_ROOT = REPO_ROOT / "ui"
CODEGEN = UI_ROOT / "node_modules" / ".bin" / "chanx-codegen"

HEADER = """\
// Generated by scripts/contracts.py from the {kit} kit ({contract}). Do not edit.
// Regenerate with: python scripts/contracts.py build
"""


def load_yaml(path: Path) -> dict[str, Any]:
    return yaml.safe_load(path.read_text()) or {}


def defined_contracts() -> dict[str, tuple[str, str]]:
    """``name@version`` -> (kit directory, contract topic class)."""
    found: dict[str, tuple[str, str]] = {}
    for manifest in sorted((REPO_ROOT / "python" / "kits").glob("*/kit.yaml")):
        data = load_yaml(manifest)
        if data.get("defines"):
            found[str(data["defines"])] = (
                manifest.parent.name,
                str(data["contract_topic"]),
            )
    return found


def consumers() -> dict[Path, str]:
    """UI kit directory -> the contract its ``contract.ts`` carries."""
    found: dict[Path, str] = {}
    for manifest in sorted((UI_ROOT / "kits").glob("*/kit.yaml")):
        consumes = load_yaml(manifest).get("consumes") or []
        if consumes:
            found[manifest.parent] = str(consumes[0])
    return found


def asyncapi_for(kit: str, topic_name: str) -> str:
    """The AsyncAPI document of an app listing only the contract topic."""
    from chanx.core.decorators import channel
    from chanx.core.topic import Topic
    from chanx.fast_channels import asyncapi_spec_json
    from chanx.fast_channels.type_defs import AsyncAPIConfig
    from chanx.fast_channels.websocket import AsyncJsonWebsocketConsumer
    from fastapi import FastAPI
    from fastapi.requests import Request
    from fastapi.responses import JSONResponse
    from fastapi.testclient import TestClient

    base = getattr(importlib.import_module(f"kits.{kit}"), topic_name)
    # Same name as the base, so nothing kit-specific leaks into the generated names.
    contract_topic = type(topic_name, (base,), {"pattern": "contract"})

    @channel(name="contract")
    class ContractConsumer(AsyncJsonWebsocketConsumer[Any]):
        topics: ClassVar[list[type[Topic[Any]]]] = [contract_topic]

    app = FastAPI()
    ws = FastAPI()
    ws.router.add_websocket_route("/contract", ContractConsumer.as_asgi())
    app.mount("/ws", ws)

    @app.get("/asyncapi.json")
    async def spec(request: Request) -> JSONResponse:
        return await asyncapi_spec_json(
            request=request, app=app, config=AsyncAPIConfig(version="1")
        )

    return TestClient(app).get("/asyncapi.json").text


UNION = re.compile(r"^export type Contract\w+?(ToServer|ToClient) = (.+);$", re.M)
# Error payloads every chanx server documents; part of the protocol, not a contract.
PROTOCOL_TYPES = re.compile(
    r"^/\*\*[^\n]*\*/\nexport interface (?:ProblemDetails|ValidationFailure) \{.*?^\}\n\n?",
    re.M | re.S,
)
DOC_COMMENT = re.compile(r"^[ \t]*/\*\*.*\*/\n", re.M)
# Differences a server library cannot avoid yet: (language, kit) -> (Python's line, the port's).
KNOWN_GAPS = {
    # chanx-js requires a payload even when its schema has a default.
    ("js", "room-chat"): [
        (
            "  payload?: ChatBacklogRequestPayload;",
            "  payload: ChatBacklogRequestPayload;",
        )
    ],
}
# How each implementation prints the spec of an app hosting one kit's contract topic.
PORT_SPECS = {
    "go": (REPO_ROOT / "go", ["go", "run", "./internal/contract"]),
    "js": (REPO_ROOT / "js", ["npx", "--no-install", "tsx", "scripts/contract.ts"]),
}


def python_spec(kit: str, topic_name: str) -> str:
    # One process per contract: chanx registers consumers globally.
    return subprocess.run(
        [sys.executable, __file__, "spec", kit, topic_name],
        check=True,
        capture_output=True,
        text=True,
    ).stdout


def port_spec(language: str, kit: str) -> str:
    cwd, command = PORT_SPECS[language]
    return subprocess.run(
        [*command, kit], cwd=cwd, check=True, capture_output=True, text=True
    ).stdout


def implementations() -> list[tuple[str, str, str]]:
    """``(language, kit id, contract)`` for every Go and JS kit implementing one."""
    found: list[tuple[str, str, str]] = []
    for language in PORT_SPECS:
        for manifest in sorted((REPO_ROOT / language / "kits").glob("*/kit.yaml")):
            data = load_yaml(manifest)
            found += [
                (language, str(data["name"]), str(c))
                for c in data.get("implements") or []
            ]
    return found


def render(kit: str, contract: str, spec_json: str) -> str:
    if not CODEGEN.exists():
        raise SystemExit(f"{CODEGEN} is missing. Run: npm ci --prefix ui")

    with tempfile.TemporaryDirectory() as tmp:
        spec = Path(tmp) / "asyncapi.json"
        spec.write_text(spec_json)
        out = Path(tmp) / "generated"
        subprocess.run(
            [str(CODEGEN), str(spec), "-o", str(out)],
            check=True,
            capture_output=True,
        )
        schemas = (out / "schemas.ts").read_text()
        channels = (out / "channels.ts").read_text()

    unions = dict(UNION.findall(channels))
    body = schemas.split("\n", 3)[3].lstrip("\n")  # drop codegen's own header
    body = PROTOCOL_TYPES.sub("", body)
    return (
        HEADER.format(kit=kit.replace("_", "-"), contract=contract)
        + "\n"
        + body.rstrip("\n")
        + "\n\n/** What a client may send on a topic speaking this contract. */\n"
        + f"export type ContractToServer = {unions.get('ToServer', 'never')};\n"
        + "/** What such a topic sends to the client. */\n"
        + f"export type ContractToClient = {unions.get('ToClient', 'never')};\n"
    )


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("command", choices=["build", "check", "spec"])
    parser.add_argument("spec_args", nargs="*", help=argparse.SUPPRESS)
    args = parser.parse_args()

    sys.path.insert(0, str(REPO_ROOT / "python"))
    if args.command == "spec":
        print(asyncapi_for(*args.spec_args))
        return 0
    defined = defined_contracts()
    stale: list[str] = []

    for directory, contract in consumers().items():
        if contract not in defined:
            print(f"{directory.name}: consumes undefined {contract}", file=sys.stderr)
            return 1
        kit, topic_name = defined[contract]
        rendered = render(kit, contract, python_spec(kit, topic_name))
        target = directory / "contract.ts"
        if args.command == "build":
            target.write_text(rendered)
            print(f"Wrote {target.relative_to(REPO_ROOT)} ({contract})")
        elif not target.exists() or target.read_text() != rendered:
            stale.append(str(target.relative_to(REPO_ROOT)))

    if stale:
        print(
            "Stale contracts: " + ", ".join(stale) + ". "
            "Run: python scripts/contracts.py build",
            file=sys.stderr,
        )
        return 1
    if args.command == "check":
        if drifted := port_drift(defined):
            print("\n".join(drifted), file=sys.stderr)
            return 1
        print("Contracts OK.")
    return 0


def port_drift(defined: dict[str, tuple[str, str]]) -> list[str]:
    """Go and JS kits whose contract types differ from the Python kit's."""
    drifted: list[str] = []
    for language, kit, contract in implementations():
        python_kit, topic_name = defined[contract]
        # Docs are not the wire: compare the types alone.
        expected = DOC_COMMENT.sub(
            "", render(python_kit, contract, python_spec(python_kit, topic_name))
        )
        actual = DOC_COMMENT.sub(
            "", render(python_kit, contract, port_spec(language, kit))
        )
        for python_line, port_line in KNOWN_GAPS.get((language, kit), []):
            expected = expected.replace(python_line, port_line)
        if actual != expected:
            diff = difflib.unified_diff(
                expected.splitlines(),
                actual.splitlines(),
                f"python/{python_kit}",
                f"{language}/{kit}",
                lineterm="",
            )
            drifted.append(
                f"{language}/{kit} drifts from {contract}:\n" + "\n".join(diff)
            )
    return drifted


if __name__ == "__main__":
    raise SystemExit(main())
